pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testRegression_property() public {
        Token token = new Token();
        token.mint(address(1), 100);

        vm.prank(address(1));
        token.approve(address(c), 100);

        address[] memory tos = new address[](2);
        tos[0] = address(2);
        tos[1] = address(3);
        uint[] memory amounts = new uint[](2);
        amounts[0] = 50;
        amounts[1] = 50;

        c.transfer(address(1), address(token), tos, amounts);

        assertEq(token.balanceOf(address(2)), 50);
        assertEq(token.balanceOf(address(3)), 50);
    }
}

contract Token {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) public {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount, "allowance too low");
        require(balanceOf[from] >= amount, "balance too low");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}
